'use strict';
let D;let STATE={view:'archive',order:'source',mode:'read',edits:false,hideDeleted:false,tab:'coverage',model:'graph',audit:'findings',category:'מושג',selectedT:null,search:'',custom:null};
let PBY={},ENT={},TOK={},NOTE_ORDER={},OBS=null,MEDIA={};
let TAG=window.__TAGGING_LAYER__||{status:'unavailable',schema:{},records:[],counts:{},diagnostics:[]};
let DIST={lens:'overview',norm:'absolute',scale:'text',unit:null,category:'מושג',editorial:'all',notesPage:0,networkPick:null};
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const short=x=>String(x??'').replace('A228401-','');
const keys=o=>Object.keys(o);const values=o=>Object.values(o);const A='A228401';
const label=id=>D.scenes[id]?.title||D.text_records[id]?.title||D.roles[id]?.character||D.persons[id]?.name||D.graphics[id]?.note||D.graphics[id]?.kind||id;
const btn=(text,action,value='',cls='btn')=>`<button class="${cls}" data-action="${action}" data-value="${esc(value)}">${text}</button>`;
const badge=(text,c='')=>`<span class="badge ${c}">${esc(text)}</span>`;
const tidSort=(a,b)=>Number(a.split('-T')[1])-Number(b.split('-T')[1]);
const sourceOrder=()=>keys(D.text_records).sort(tidSort);
const programOrder=()=>values(D.program_items).sort((a,b)=>a.order-b.order);
const txts=sid=>values(D.text_records).filter(t=>t.target===sid).sort((a,b)=>tidSort(a.id,b.id));
const psFor=sid=>programOrder().filter(p=>p.target===sid);
const htmlURL=u=>/^https?:\/\//i.test(String(u))?esc(u):'#';
function linkify(s){return String(s??'').split(/(https?:\/\/[^\s<>]+)/g).map(v=>/^https?:\/\//.test(v)?`<a href="${htmlURL(v)}" target="_blank" rel="noopener noreferrer">קישור במקור</a>`:esc(v)).join('')}
function safeLink(url,title){return `<a class="btn" href="${htmlURL(url)}" target="_blank" rel="noopener noreferrer">${esc(title)}</a>`}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('on');setTimeout(()=>$('#toast').classList.remove('on'),2200)}
function pop(kicker,html){$('#detailKicker').textContent=kicker;$('#detailBody').innerHTML=html; const title=$('#detailBody h2');if(title){title.id='detailTitle';$('#detail').setAttribute('aria-labelledby','detailTitle')}if(!$('#detail').open)$('#detail').showModal();$('#detail').scrollTop=0}
function closePop(){if($('#detail').open)$('#detail').close()}
function dl(obj){return `<dl class="record-dl">${Object.entries(obj).map(([k,v])=>`<dt>${esc(k)}</dt><dd>${esc(v??'—')}</dd>`).join('')}</dl>`}
function sheet(name){return D.sheets.find(s=>s.name===name)}
function cellLabel(rec,col=''){return `${rec.sheet}!${col}${rec.row}`}
function recordButton(rec,txt='רשומת המיפתוח'){return btn(esc(txt)+' <span class="source-locator">'+esc(cellLabel(rec))+'</span>','record',rec.sheet+'|'+rec.row)}
function openRecord(value){let[n,r]=value.split('|');let s=sheet(n),rec=s?.relevant_records.find(x=>x.row===+r);if(!rec){pop('רשומה',`<h2>אין רשומה להצגה במיקום זה</h2><p>${esc(value)}</p>`);return}let obj={};rec.values.forEach((v,i)=>{if(v!==null&&v!=='')obj[(s.headers[i]||`עמודה ${String.fromCharCode(65+i)} ללא כותרת`)+` [${String.fromCharCode(65+i)}${rec.row}]`]=v});pop('נתוני מקור · ללא תיקון שקט',`<h2>${esc(n)}</h2><p class="small">שורה ${r} · צילום הגיליון מ־12.10.26. אפס, תא ריק ושגיאת נוסחה נשמרים כמצבים שונים.</p>${dl(obj)}`)}
function parseTokens(p){if(TOK[p.id])return TOK[p.id];let special=[];
 const add=(regex,kind)=>{for(let m of p.text.matchAll(regex))special.push({a:m.index,b:m.index+m[0].length,kind,text:m[0],id:m[1]})};
 add(/<\/?(A228401-T\d+(?:\.[^>]*)?)>/g,'struct');add(/<(A228401-R\d+)>/g,'role');add(/\[\[(\/?(?:MOVE|SWAP|TARGET)-[^\]]+)\]\]/g,'operation');add(/(\/{4})/g,'end');
 if(p.runs.some(r=>r.semantics.includes('page_marker')))add(/<(\d+)>/g,'page');
 for(let e of ENT[p.n]||[])special.push({a:e.a,b:e.b,kind:'entity',entity:e,text:e.raw});
 // Editorial source/replacement delimiter: keep both readings, don't guess where a replacement ends.
 for(let m of p.text.matchAll(/<([^<>]+)>>/g))if(!special.some(s=>s.a<=m.index&&s.b>m.index))special.push({a:m.index,b:m.index+m[0].length,kind:'correction',text:m[0],old:m[1]});
 special.sort((a,b)=>a.a-b.a);
 let out=[];for(let r of p.runs){let pos=r.a;while(pos<r.b){let sp=special.find(s=>s.a<=pos&&s.b>pos);if(sp){if(pos===sp.a)out.push({...sp,sem:r.semantics});pos=Math.min(r.b,sp.b);continue}let end=Math.min(r.b,...special.filter(s=>s.a>pos).map(s=>s.a));out.push({a:pos,b:end,kind:'text',text:p.text.slice(pos,end),sem:r.semantics});pos=end}for(let f of r.footnotes)out.push({kind:'footnote',id:f,a:r.a,b:r.a,sem:[]})}
 TOK[p.id]=out;return out;
}
function tagForParagraph(p){return TAG.records.filter(r=>r.alignment?.paragraph===p.n&&r.alignment?.status==='anchored_exact')}
function tagHighlightedToken(t,p){
 let tags=tagForParagraph(p).filter(r=>r.alignment.end>t.a&&r.alignment.start<t.b);
 if(!tags.length)return STATE.mode==='linked'&&(t.sem||[]).length?`<button class="sem-tap sem ${(t.sem||[]).join(' ')}" data-action="runinfo" data-value="${p.n}|${t.a}|${t.b}" title="פתחו את כל סימוני XML בחלק זה">${esc(t.text).replace(/#{1,}/g,m=>`<span class="unclear" title="אותיות לא מפוענחות">${m}</span>`)}</button>`:`<span class="sem ${(t.sem||[]).join(' ')}">${esc(t.text).replace(/#{1,}/g,m=>`<span class="unclear" title="אותיות לא מפוענחות">${m}</span>`)}</span>`;
 let bounds=new Set([t.a,t.b]);for(const r of tags){bounds.add(Math.max(t.a,r.alignment.start));bounds.add(Math.min(t.b,r.alignment.end))}
 let bb=[...bounds].sort((a,b)=>a-b),html='';
 for(let i=0;i<bb.length-1;i++){
  const a=bb[i],b=bb[i+1],txt=esc(p.text.slice(a,b));
  const r=tags.find(x=>x.alignment.start<=a&&x.alignment.end>=b);
  html+=r?`<mark class="newtag-mark" data-action="tagrecord" data-value="${esc(r.id)}" tabindex="0" title="תיוג מחקרי: ${esc(r.sheet)}">${txt}</mark>`:txt;
 }
 return STATE.mode==='linked'&&(t.sem||[]).length?`<button class="sem-tap sem ${(t.sem||[]).join(' ')}" data-action="runinfo" data-value="${p.n}|${t.a}|${t.b}" title="צפייה בסימוני XML של מקטע זה">${html}</button>`:`<span class="sem ${(t.sem||[]).join(' ')}">${html}</span>`;
}
function tokenHTML(t,p){let layered=STATE.mode==='linked';switch(t.kind){
 case 'struct':return layered?`<span class="markup">${esc(t.text)}</span>`:'';
 case 'role':return `<button class="role-ref" data-action="role" data-value="${esc(t.id)}" title="תפקיד: ${esc(label(t.id))} · ${esc(D.roles[t.id]?.actor||'שחקן לא מזוהה')}" aria-label="פרטי התפקיד ${esc(label(t.id))}">${layered?esc(short(t.id)):'↗'}</button>`;
 case 'entity':return `<button class="person-ref" data-action="${t.entity.person?'person':'unresolved'}" data-value="${esc(t.entity.person||t.entity.name)}" title="זיהוי אדם לפי שם מפורש במהדורה ובמיפתוח">[${esc(t.entity.name)}]</button>`;
 case 'end':return '<span class="mark-end" title="סיום רפליקה"> ⌁ </span>';
 case 'operation':return layered?`<button class="markup" data-action="operations" title="פעולת עריכה">${esc(t.text)}</button>`:'';
 case 'page':return '';
 case 'correction':return `<span class="correction-token" title="קריאת המקור, ולאחריה הצעת תיקון של המהדירים">${esc(t.old)} ⇢ </span>`;
 case 'footnote':return `<button class="fn" data-action="note" data-value="${t.id}" aria-label="הערה ${D.footnotes[t.id]?.display_number||t.id}">${D.footnotes[t.id]?.display_number||t.id}</button>`;
 default:return tagHighlightedToken(t,p);
}}
function renderSlice(p,a,b){return parseTokens(p).filter(t=>t.a>=a&&t.b<=b).map(t=>tokenHTML(t,p)).join('')}
function paragraphHTML(p){let onlyCode=/^\s*<\/?A228401-T\d+>\s*$/.test(p.text);if(!p.text.trim()&&!p.footnotes.length)return '';if(onlyCode&&STATE.mode!=='linked'&&STATE.mode!=='code')return '';
 if(STATE.mode==='code')return `<div class="raw-code" id="p-${p.n}"><span class="source-locator">${p.id} · ${esc(short(p.t))}</span><span class="raw-line">${esc(p.text)}</span>${p.footnotes.length?'<span class="mini">footnoteReference: '+p.footnotes.join(', ')+'</span>':''}<details><summary>מאפייני מקטעי העיצוב</summary>${esc(JSON.stringify(p.runs.filter(r=>r.text||r.footnotes.length).map(r=>({text:r.text,style:r.properties,semantics:r.semantics,notes:r.footnotes})),null,2))}</details></div>`;
 let pm=p.runs.some(r=>r.semantics.includes('page_marker')),pn=p.text.match(/<(\d+)>/);if(pm&&pn){let extra=p.text.replace(/<\d+>/,'').trim();return `<div class="page-mark" id="p-${p.n}">${btn('עמוד קובץ '+pn[1]+(extra?' · מספור בנייר: '+esc(extra):''),'page',String(p.n))}</div>`}
 let validSwap=STATE.edits&&D.operations.find(o=>o.kind==='SWAP'&&o.valid&&o.spans[0].open.p===p.n);
 let content;if(validSwap){let[a,b]=validSwap.spans.slice().sort((a,b)=>a.open.a-b.open.a);content=renderSlice(p,0,a.open.a)+`<span class="edit-applied">חילוף ע״פ SWAP ${esc(validSwap.id)}</span> `+renderSlice(p,b.open.b,b.close.a)+renderSlice(p,a.close.b,b.open.a)+renderSlice(p,a.open.b,a.close.a)+renderSlice(p,b.close.b,p.text.length)}else content=parseTokens(p).map(t=>tokenHTML(t,p)).join('');
 let bad=D.operations.find(o=>o.kind==='SWAP'&&!o.valid&&o.events.some(e=>e.p===p.n));if(bad)content+='<span class="edit-applied">SWAP לא מופעל — סגירה לא תואמת</span>';
 for(const c of D.comments.filter(c=>c.paragraphs?.includes(p.n)))content+=' '+btn('הערת עבודה','comment',c.id,'fn');
 const residual=D.residuals.find(r=>r.p===p.n);if(residual&&STATE.mode==='read')return `<div id="p-${p.n}" class="banner problem">בשורת הקוד נשמר גם הטקסט ${esc(JSON.stringify(residual.text))}. הוא מוצג כאן כחריגת מקור, לא כחלק מאומת מן המחזה. ${btn('הקידוד','xmlpara',p.n)}</div>`;
 if(!content.trim())return '';let tags=TAG.records.filter(r=>r.alignment?.paragraph===p.n&&['anchored_exact','paragraph_only'].includes(r.alignment?.status));
 let extras=tags.length?` <button class="tag-inline-badge" data-action="tagrecord" data-value="${esc(tags[0].id)}" title="${tags.length} תיוגים נוספים מן הקובץ החדש">${tags.length} תיוגים</button>`:'';
 return `<p id="p-${p.n}" data-p="${p.n}" class="${p.runs.some(r=>r.semantics.includes('heading'))?'source-heading':''}">${content}${extras}</p>`;
}
function orderedParagraphs(tid){let arr=D.segments[tid].paragraphs.map(id=>PBY[id]);if(STATE.edits&&STATE.mode!=='code'){for(let o of D.operations.filter(o=>o.kind==='MOVE'&&o.valid&&o.source.open.t===tid)){let content=arr.filter(p=>p.n>o.source.open.p&&p.n<o.source.close.p);arr=arr.filter(p=>!content.includes(p));let ix=arr.findIndex(p=>p.n===o.target.p);if(ix>=0)arr.splice(ix+1,0,...content)}}return arr}
function castOf(sid){return values(D.roles).filter(r=>r.s===sid)}
function castStripHTML(sid){let rs=castOf(sid);if(!rs.length)return '';
 return `<details class="cast-strip"><summary><b>משתתפים ותפקידים — ${rs.length}</b><span>${rs.filter(r=>!!D.persons[r.person]).length} שיוכים מזוהים${rs.some(r=>!D.persons[r.person])?' · שיוכים חסרים':''}</span></summary><div class="cast-strip-inner">${rs.map(r=>`<div class="cast-row"><button data-action="role" data-value="${esc(r.id)}" title="רשומת התפקיד">${esc(r.character)}</button><span>—</span>${D.persons[r.person]?btn(esc(r.actor),'person',r.person,'actor-link'):`<span class="cast-unresolved">שחקנ.ית לא מזוהה</span>`}<small>${esc(short(r.id))}</small></div>`).join('')}</div><p class="cast-notice">זהו שיוך התפקידים במיפתוח, לא זיהוי אוטומטי של זהות הדובר בכל שורה. קוד R בגוף הטקסט מפנה לרשומת התפקיד.</p></details>`;
}
function unitInlineNotes(tid){let notes=values(D.footnotes).flatMap(f=>(f.occurrences||[]).filter(o=>o.t===tid).map(o=>({f,o}))).sort((a,b)=>a.o.p-b.o.p);if(!notes.length)return '';return `<details class="inline-notes"><summary>הערות המהדורה במקטע זה · ${notes.length} <span>פתיחה, חיפוש בעין וחזרה לפסקת המקור</span></summary><div class="inline-notes-list">${notes.map(({f,o})=>`<article><b>${f.display_number||f.id}</b><div><small>${esc((f.categories||[]).join(' · ')||'הערה ללא סיווג')}</small><p>${esc(f.text)}</p>${btn('לפסקה בהצגה','distantJump',tid+'|'+o.p)}</div></article>`).join('')}</div></details>`}
function tHTML(tid){let t=D.text_records[tid],seg=D.segments[tid];if(!seg)return '';let s=t.target;let counts=seg.footnote_count;let header=`<header><div><span class="kicker">${esc(t.genre)} · ${esc(short(tid))}</span><h2>${esc(t.title)}</h2><div class="t-meta">${s===A?badge('שער ברמת ההצגה'):btn(esc(label(s)),'unit',s,'meta-chip')}${badge(counts+' הערות')}${badge(seg.role_ids.length+' קודי תפקיד')}</div></div>${btn('נתוני היחידה','textrecord',tid)}</header>`;
 return `<section class="text-segment" id="section-${tid}" data-tid="${tid}">${header}${s!==A?castStripHTML(s):''}<div class="text-body">${orderedParagraphs(tid).map(paragraphHTML).join('')}${tid.endsWith('-T16')?'<div class="banner">בעד זה מופיעות שתי כותרות בכתב יד — „הטנדר נוסע!” ו„טנדר”. גוף השיר אינו נמצא כאן. '+btn('מילות השיר בתכנייה','program','2')+'</div>':''}${STATE.edits&&tid.endsWith('-T7')?'<div class="banner good">בלוק השיר הוצג ביעד MOVE המסומן. מיקומי המקור ומזהי הפסקאות נשמרו; אפשר לחזור בכל רגע לסדר העד.</div>':''}${unitInlineNotes(tid)}</div></section>`;
}
function mapOrder(){if(STATE.order==='program')return programOrder().map(p=>p.target);let seen=[];for(let tid of sourceOrder()){let s=D.text_records[tid].target;if(!seen.includes(s))seen.push(s)}return seen}
function mapHTML(){return `<div class="atlas" aria-label="מפת קריאה">${mapOrder().map(s=>{let p=psFor(s)[0],isBreak=['A228401-S4','A228401-S8'].includes(s),ts=txts(s);return `<button data-action="jumpunit" data-value="${esc(s)}" class="${s.endsWith('-S10')?'partial':s.endsWith('-S12')?'unmatched':''} ${isBreak?'break':''}" title="${esc(label(s))}"><small>${s===A?'שער':isBreak?'הפסקה':p?'סדר MD '+p.order:'טקסט בלבד'}</small>${esc(s===A?'שער ההצגה':label(s))}</button>`}).join('')}</div>`}
function renderRead(){let compared=STATE.order==='compare';$('#content').innerHTML=`<section class="hero"><div><span class="kicker">המטאטא · תכנית נ״א · 1939</span><h1>כי תצא למלחמה</h1><p>לקרוא את ההצגה, ולראות ממה הקריאה בנויה. הטקסט, התכנייה והערות המחקר נשארים נפרדים — הקשרים מאפשרים לעבור ביניהם בלי למחוק את ההבדלים.</p></div><div class="hero-side"><b>21 יחידות טקסט</b><br>529 הערות מקושרות<br>42 זהויות של תפקידים<br><span class="mini">ה־XML החדש והמיפתוח הנוכחי,<br>לא נתוני ההדגמה הישנים.</span></div></section><section class="read-bar">${mapHTML()}<div class="read-options"><div class="seg-control" role="group" aria-label="סדר קריאה">${[['source','סדר הטקסט'],['program','לפי התכנייה'],['compare','השוואת רצפים']].map(([v,t])=>`<button data-order="${v}" class="${STATE.order===v?'on':''}">${t}</button>`).join('')}</div><div class="seg-control">${[['read','קריאה'],['linked','שכבות העריכה'],['code','קוד המהדורה']].map(([v,t])=>`<button data-mode="${v}" class="${STATE.mode===v?'on':''}">${t}</button>`).join('')}</div><input id="textSearch" type="search" placeholder="חיפוש בטקסט ובהערות…" aria-label="חיפוש בטקסט ובהערות" value="${esc(STATE.search)}"></div>${STATE.mode==='linked'?`<div class="sem-filter-bar"><b>שכבות ה־XML: </b><button data-runfocus="all" class="${RUN_FOCUS==='all'?'on':''}">הכול</button>${DIST_SEM.map(k=>`<button data-runfocus="${k}" class="${RUN_FOCUS===k?'on':''}">${DIST_HE[k]}</button>`).join('')}<small>לחיצה על מילה מסומנת פותחת את מאפייני המקור המדויקים.</small></div>`:''}<div class="mobile-read-tools">${btn('אפשרויות קריאה ועריכה','reading-options')}${btn('מפתח הסימנים','legend')}${btn('פעולות הזזה','operations')}</div><div id="searchResults"></div></section><div class="reading-layout"><div data-sem-filter="${RUN_FOCUS}" class="reader ${STATE.mode==='linked'?'layered':''} ${STATE.hideDeleted?'hidden-deletions':''}">${compared?compareHTML():readingBody()}</div><aside class="reading-aside"><div class="panel"><h3>איזו קריאה זו?</h3><p>${STATE.order==='program'?'רצף המבוסס על רשומות PS. המספור הפנימי כולל הפסקות; הוא אינו זהה למספרי הקטעים המודפסים.':'סדר יחידות T בקובץ המקור. הוא נשמר גם כאשר סדר התכנייה שונה.'}</p><p class="small">מחיקה נשמרת בטקסט. שם אדם בסוגריים הוא זיהוי שהוסיפו המהדירים. לחיצה על מספר קטן פותחת את ההערה.</p>${btn('על מפתח הסימנים','legend')}${btn('כל התפקידים והשחקנים','materialsTab','cast')}</div><div class="panel"><h3>ניסוי עריכתי</h3><label><input id="editToggle" type="checkbox" ${STATE.edits?'checked':''}> הפעלת הזזות תקינות</label><p class="small">MOVE אחד ושני זוגות SWAP. הזוג בעמוד 56 חסום בגלל אי־התאמה בסגירה.</p><label><input id="deleteToggle" type="checkbox" ${STATE.hideDeleted?'checked':''}> הסתרת הטקסט המחוק</label><p class="small">בחירת תצוגה בלבד; המקור אינו משתנה.</p>${btn('בדיקת פעולות העריכה','operations')}</div><div class="panel"><h3>מן הקריאה למחקר</h3>${btn('מפת הכיסוי','view','materials')}${btn('מפת הידע','view','model')}${btn('ממצאים ובדיקות','view','audit')}</div></aside></div>`;wireObserver();if(STATE.search)searchNow(STATE.search);$('#textSearch').addEventListener('input',e=>{STATE.search=e.target.value;searchNow(e.target.value)})}
function readingBody(){if(STATE.order==='source')return sourceOrder().map(tHTML).join('');let html=tHTML(A+'-T1');for(let p of programOrder()){let ts=txts(p.target);if(!ts.length)html+=`<div class="source-break">${esc(p.title)} · רשומת ${short(p.target)} · אין יחידת T</div>`;else html+=ts.map(t=>tHTML(t.id)).join('');if(p.target===A+'-S10')html+=`<section class="panel"><h3>מילות „הטנדר נוסע” בתכנייה</h3><p class="small">מקור אחר, לא השלמה בלתי מסומנת של הטקסט. צילום התכנייה זמין; לא הוכנס כאן התמלול החלקי הישן.</p>${btn('פתיחת התכנייה לקריאה','program','2')}</section>`}html+=`<div class="banner">מחוץ לרצף התכנייה: ${btn('„בחזית המלך פיק” — בטקסט','jump',A+'-T10')}. אי־הכללה בקריאה הזאת אינה קביעה שלא בוצע.</div>`;return html}
function compareHTML(){let side=(items,program)=>`<div class="compare-col"><h2>${program?'לפי התכנייה':'לפי קובץ הטקסט'}</h2><ul class="compare-list">${items.map((s,i)=>`<li><span class="num">${i+1}</span><span style="flex:1">${esc(s===A?'שער כללי':label(s))}<br><span class="small">${txts(s).map(t=>short(t.id)).join(' · ')||'ללא T'}</span></span>${btn('לקריאה','jumpunit',s)}${btn('עדויות','unit',s)}</li>`).join('')}</ul></div>`;let so=[];sourceOrder().forEach(t=>{let s=D.text_records[t].target;if(!so.includes(s))so.push(s)});return `<div class="grid2">${side(programOrder().map(p=>p.target),true)}${side(so,false)}</div><div class="banner">שתי רשימות, שתי פעולות ארגון. S12 נמצאת ברצף הטקסט; S4 ו־S8 מייצגות הפסקות בתכנייה. היחס בין „הטנדר נוסע” לבין „קו מז׳ינו” משתנה.</div>`}
function wireObserver(){if(OBS)OBS.disconnect();OBS=new IntersectionObserver(es=>{let e=es.find(x=>x.isIntersecting);if(e){STATE.selectedT=e.target.dataset.tid;let s=D.text_records[STATE.selectedT]?.target;$$('.atlas [data-value]').forEach(b=>b.classList.toggle('selected',b.dataset.value===s))}},{rootMargin:'-230px 0px -55% 0px',threshold:0});$$('.text-segment').forEach(el=>OBS.observe(el))}
function jump(tid,pn=null){closePop();if(!D.text_records[tid])return;if(STATE.view!=='read'||STATE.order==='compare'||(STATE.order==='program'&&!psFor(D.text_records[tid].target).length&&D.text_records[tid].target!==A)){STATE.view='read';STATE.order='source';render()}STATE.selectedT=tid;let e=document.getElementById(pn?'p-'+pn:'section-'+tid);if(e){e.scrollIntoView({block:'start',behavior:'smooth'});if(pn){$$('.para-focus').forEach(x=>x.classList.remove('para-focus'));e.classList.add('para-focus')}}setHash()}
function searchNow(q){let box=$('#searchResults');if(!box)return;if(q.trim().length<2){box.innerHTML='';return}let hits=[];for(let p of D.paragraphs)if(p.t&&p.text.includes(q))hits.push({t:p.t,p:p.n,text:p.text.replace(/<[^>]+>/g,'').slice(0,160),kind:'טקסט'});for(let f of values(D.footnotes))if(f.text.includes(q)){let o=f.occurrences[0];if(o)hits.push({t:PBY['xml-p'+String(o.p).padStart(4,'0')]?.t,p:o.p,text:f.text.slice(0,170),kind:'הערה '+f.display_number})}box.innerHTML=`<div class="search-results"><b>${hits.length} פסקאות/הערות תואמות</b> · ${hits.length>60?'מציג 60 ראשונות':'לחצו למעבר למקור'}${hits.slice(0,60).map(h=>`<button class="search-result" data-action="jump" data-value="${h.t}|${h.p}">${badge(h.kind)} ${esc(short(h.t))} — ${esc(h.text)}</button>`).join('')}</div>`}
function openNote(id){let f=D.footnotes[id];if(!f)return;let loc=f.occurrences[0];pop('הערת המהדירים · נוסח המקור',`<h2>הערה ${f.display_number}</h2><div class="footnote-text">${linkify(f.text)}</div><div class="pills">${f.categories.map(c=>btn(esc(c),'category',c)).join('')}</div><div class="detail-links">${(f.links||[]).filter(x=>x.target).map(x=>safeLink(x.target,'קישור בהערה')).join('')}${loc?btn('חזרה למקום בטקסט','jump',PBY['xml-p'+String(loc.p).padStart(4,'0')]?.t+'|'+loc.p):''}</div><p class="small">מספר פנימי בקובץ: ${id}. ההערה מובאת כדברי המהדירים; המקורות החיצוניים שהיא מפנה אליהם לא נבדקו כאן מחדש.</p>`)}
function openPerson(id){let p=D.persons[id];if(!p)return;let rs=values(D.roles).filter(r=>r.person===id);let es=D.entity_mentions.filter(e=>e.person===id);pop('ישות אדם · שימור ההבחנה בין אדם לתפקיד',`<h2>${esc(p.name)}</h2><p class="small">${esc(id)} · ${rs.length} תפקידים רשומים בהצגה · ${es.length} זיהויי שם במהדורה</p><div class="grid2">${rs.map(r=>`<div class="step">${btn(esc(r.character),'role',r.id)}<span>${esc(label(r.s))}</span></div>`).join('')}</div><div class="detail-links">${recordButton(p.record)}${es.map(e=>btn('אזכור ב־'+short(e.t),'jump',e.t+'|'+e.p)).join('')}</div>${dl({'Wikidata במיפתוח':p.wikidata,'VIAF במיפתוח':p.viaf})}<p class="small">חיבורים משמות מסומנים בטקסט לרשומה הזאת מסומנים כהתאמה ייחודית של שם; אין ב־Word עצמו קוד per מפורש בכל אזכור.</p>`)}
function openRole(id){let r=D.roles[id];if(!r)return;let occ=D.paragraphs.filter(p=>p.role_refs.some(x=>x.id===id));pop('תפקיד דרמטי · R',`<h2>${esc(r.character)}</h2><div class="path">${btn(esc(short(id)),'record',r.record.sheet+'|'+r.record.row)} ← ${D.persons[r.person]?btn(esc(r.actor),'person',r.person):badge('השחקן/ית אינם ידועים; במקור #N/A','warn')}</div><p>${btn(esc(label(r.s)),'unit',r.s)}</p>${r.note?`<div class="banner">${esc(r.note)}</div>`:''}<p class="small">${occ.length} פסקאות עם קוד התפקיד. אלה אזכורי קוד, לא בהכרח מספר רפליקות: קוד יכול להופיע גם בהוראת בימוי.</p><div class="pills">${occ.slice(0,30).map(p=>btn(short(p.t)+' · פסקה '+p.n,'jump',p.t+'|'+p.n)).join('')}</div><div class="detail-links">${recordButton(r.record)}</div>`)}
function openUnit(id){if(id===A){pop('רמת ההצגה',`<h2>${esc(D.production.title)}</h2>${recordButton(D.production.record)}`);return}let s=D.scenes[id];if(!s)return;let ts=txts(id),ps=psFor(id),roles=values(D.roles).filter(r=>r.s===id),av=D.media.filter(m=>m.target===id);pop('תיק יחידת מחקר · S אינה עד חומרי',`<h2>${esc(s.title)}</h2><p class="small">${esc(id)} · ${ts.length} יחידות T · ${ps.length} רשומות PS · ${roles.length} תפקידים</p><h3>מה נשמר ומה קושר במיפתוח?</h3><div class="grid2">${ts.map(t=>`<div class="step"><b>${esc(t.title)}</b><span>${esc(short(t.id))} → ${esc(short(id))} · שדה F</span>${btn('קריאת המקור','jump',t.id)} ${recordButton(t.record)}</div>`).join('')}${ps.map(p=>`<div class="step"><b>${esc(p.title)}</b><span>${esc(short(p.id))} → ${esc(short(id))} · שדה E</span>${btn('צילום התכנייה','program','2')} ${recordButton(p.record)}</div>`).join('')}</div>${!ps.length?'<div class="banner">אין רשומת PS מקבילה בקובץ. אין להסיק מכך לבדו שהקטע לא בוצע.</div>':''}${s.note?`<h3 style="margin-top:22px">הטענה/ההערה המחקרית במיפתוח</h3><div class="footnote-text">${linkify(s.note)}</div>${recordButton(s.record)}`:''}${id.endsWith('-S10')?`<div class="banner">P1.4 מתוארת בהערה „מילות השיר הטנדר נוסע”, אך H ריק. קישור שלה לכאן הוא זיהוי לפי ההערה והכותרת, לא מפתח זר מפורש. ${btn('היחידה הגרפית','graphic',A+'-P1.4')}</div>`:''}${roles.length?'<h3 style="margin-top:22px">תפקידים ואנשים</h3><div class="pills">'+roles.map(r=>btn(esc(r.character)+(D.persons[r.person]?'':' · שיוך שחקן חסר'),'role',r.id)).join('')+'</div>':''}${av.length?'<h3 style="margin-top:22px">חומר שמע/וידאו מקושר</h3>'+av.map(m=>mediaHTML(m)).join(''):''}<div class="detail-links">${btn('השוואת קריאות','compare')}${btn('מסלול הקשרים של היחידה','focusmodel',id)}</div><p class="small">קישור מפורש בטבלה מתאר את הקטלוג. הוא אינו מדד מספרי לוודאות שהיחידה בוצעה במופע מסוים.</p>`)}
function openTextRecord(id){let t=D.text_records[id],s=D.segments[id];pop('יחידה בתוך העד · T',`<h2>${esc(t.title)}</h2><div class="path">${btn(esc(id),'jump',id)} ← ${btn(esc(label(t.target)),'unit',t.target)}</div>${dl({'סוג במיפתוח':t.genre,'פסקאות בקובץ':s.paragraph_count,'מיקום XML':s.start+'–'+s.end,'הערות שוליים':s.footnote_count,'קודי תפקיד שונים':s.role_ids.length})}<p class="small">מזהה T הוא גבול בתוך העד; יעדו יכול להיות יחידת S או ההצגה A (במקרה השער הכללי).</p>${recordButton(t.record)}${btn('קריאת כל היחידה','jump',id)}`)}
function openXMLPara(n){let p=D.paragraphs.find(p=>p.n===+n);if(!p)return;pop('XML · מיקום מקורי',`<h2>${esc(p.id)}</h2><pre class="raw-code">${esc(p.text)}</pre><p class="source-locator">${esc(p.xml_path)}</p>${dl({'T':p.t,'מזהה פסקה של Word':p.paraId,'הערות':p.footnotes.join(', ')})}<details open><summary>מקטעי Word: טקסט, עיצוב והפניות</summary><pre class="raw-code">${esc(JSON.stringify(p.runs,null,2))}</pre></details>${btn('חזרה לקריאה','jump',p.t+'|'+p.n)}`)}
function openOperations(){pop('פעולות עריכה במקור',`<h2>MOVE ו־SWAP</h2><p>הסדר המקורי נשמר. אפשר להפעיל רק פעולות שלגביהן נמצא זוג סימוני פתיחה/סגירה ויעד עקביים.</p>${D.operations.map(o=>`<section class="finding ${o.valid?'':'error'}"><h3>${o.kind} · ${esc(o.id)} ${badge(o.valid?'זוג סימונים תקין':'לא מופעל — דרוש בירור',o.valid?'':'error')}</h3><p>${o.kind==='MOVE'?'קטע מתוך עמוד 21 אל היעד המסומן לפניו; סיבת המהדירים: convention.':'חילוף בין שני מקטעים בתוך פסקה. סיבת המהדירים: edit.'}</p>${btn('למקום בטקסט','jump',o.kind==='MOVE'?o.source.open.t+'|'+o.source.open.p:o.events[0].t+'|'+o.events[0].p)}<details><summary>סימוני המקור</summary><pre class="raw-code">${esc(JSON.stringify(o,null,2))}</pre></details></section>`).join('')}<div class="banner">תקינות זוג הסימונים אינה אישור לפרשנות עצמה. זו בדיקה המאפשרת להציג את הצעת העריכה בלי לאבד את סדר העד.</div>`)}
function legend(){pop('מקרא המהדורה',`<h2>הצבעים והקודים הם מידע</h2><div class="record-dl">${[['ירוק','כתב יד במקור. אין הבחנה בין ידיים שונות.'],['חום','מחיקה דרמטורגית.'],['קו חוצה','מחיקה טקסטואלית.'],['תכלת','כתב יד בתוך קטע מחוק; נשמרים שני ההיבטים.'],['אפור','התערבות מהדירים: תיקון, השלמה או זיהוי.'],['רקע ירוק','הוראת בימוי.'],['רקע טורקיז','כותרת.'],['רקע צהוב','זיהוי שם / דובר; //// עדיין סימן סיום, לא אדם.'],['רקע ורוד','מספור עמודי קובץ ומספור בנייר, שאינם אותו דבר.'],['קוד T','גבול יחידת טקסט המקושרת למיפתוח.'],['קוד R','תפקיד דרמטי, לא מזהה אדם.'],['MOVE / SWAP','פעולות עריכה; מוחלות רק כשהתחביר עקבי.'],['####','אותיות שאינן מפוענחות.'],['הערות','529 הערות מחוברות למיקומן המקורי.']].map(([a,b])=>`<dt>${a}</dt><dd>${b}</dd>`).join('')}</div><p class="small">המקרא תומך גם בגרסאות ו־ANA. בקובץ הנוכחי לא נמצאו בלוקי ANA / V עצמאיים; אין ליצור גרסאות מלאכותיות. V1 שמופיע בסימון הזזה אינו כשלעצמו גרסת טקסט מלאה.</p>`)}function imgSrc(n){return window.__MEDIA__?.['program'+n]||'media/program'+n+'.jpg'}
function openProgram(n){let page=n==='1'?'שער התכנייה ופזמונים':'רשימת הערב ומילות „הטנדר נוסע”';pop('עד חומרי · צילום התכנייה',`<h2>${page}</h2><p class="small">שני צילומים של ארבעה עמודי תכנייה. אין להסיק מכך שתי גרסאות תכנייה שונות.</p><div class="pills">${btn('שער ופזמונים','program','1')}${btn('רשימה ומילות השיר','program','2')}${btn('הגדלה +','zoomimage','in')}${btn('הקטנה −','zoomimage','out')}</div><figure style="max-height:65vh;overflow:auto;margin:15px 0"><img class="source-image" src="${imgSrc(n)}" alt="${page}" style="width:100%" data-scale="1"></figure><p class="caption">${n==='2'?'רשימת הסצנות מימין; מילות השיר משמאל. הגדילו כדי לקרוא את האותיות.':'P1.1–P1.2 ו־P1.5–P1.6 לפי המיפתוח.'}</p><div class="pills">${values(D.graphics).filter(g=>g.image_page===+n).map(g=>btn(esc(short(g.id)+' · '+(g.note||g.kind)),'graphic',g.id)).join('')}</div>`)}
function openGraphic(id){let g=D.graphics[id];if(!g)return;pop('יחידה גרפית בתוך תכנייה · P',`<h2>${esc(g.note||g.kind)}</h2>${dl({'מזהה':id,'סוג':g.kind,'עמוד בתכנייה':g.logical_page,'צילום דיגיטלי':g.image_page,'הערת המקור':g.note,'קישור H ליחידה אמנותית':g.record.values[7]??'ריק'})}<div class="detail-links">${btn('פתח צילום','program',String(g.image_page))}${recordButton(g.record)}</div><p class="small">ריק אינו ערך שלילי. כאשר מזהים את השיר הזה עם S לפי הכותרת/ההערה, יש להציג זאת כפעולת זיהוי ולא כקישור ID מפורש.</p>`)}
function mediaHTML(m){return `<div class="finding"><h3>${esc(m.title)} ${badge(m.kind)}</h3><p>${esc(m.archive)}${m.extra?.length?' · '+esc(m.extra.filter(x=>x).join(' · ')):''}</p><p class="small">תאריך בשדה המיפתוח: ${esc(m.date||'לא צוין')}. הקישור אינו כשלעצמו תיעוד של ביצוע 1939.</p>${safeLink(m.url,'פתיחת חומר המקור')}${recordButton(m.record)}</div>`}
function renderMaterials(){let tabs=[['coverage','מפת הכיסוי'],['sources','חומרי המקור'],['notes','קריאה מרחוק'],['heatmap','מפת טקסט'],['cast','משתתפים'],['tagging','שכבת תיוג חדשה'],['scenarios','קריאות ותרחישים']];$('#content').innerHTML=`<section class="hero"><div><span class="kicker">מקור אחד אינו מסביר את הכול</span><h1>מפה וחומרים</h1><p>אילו חלקים של ההצגה מתועדים בכל מקור? מן המבט הרחב אפשר להיכנס ליחידה, לקרוא את החומר ולבחון את ההכרעה המחקרית.</p></div></section><div class="data-tabs">${tabs.map(([k,t])=>`<button data-mtab="${k}" class="${STATE.tab===k?'on':''}">${t}</button>`).join('')}</div><section id="materialsBody"></section>`;let area=$('#materialsBody');if(STATE.tab==='coverage')area.innerHTML=coverageHTML();if(STATE.tab==='sources')area.innerHTML=sourcesHTML();if(STATE.tab==='notes')area.innerHTML=notesAnalysis();if(STATE.tab==='scenarios')area.innerHTML=scenariosHTML();if(STATE.tab==='heatmap')area.innerHTML=heatmapHTML();if(STATE.tab==='cast')area.innerHTML=castAtlasHTML();if(STATE.tab==='tagging')area.innerHTML=taggingHTML()}
function coverageHTML(){return `<div class="panel"><div class="section-head"><h2>מפת הכיסוי של 12 יחידות S</h2><span class="small">מספר רשומות מקושרות — לא מספר עדים עצמאיים</span></div><div class="table-scroll"><table class="coverage"><thead><tr><th>יחידת מחקר</th><th>מקטעי טקסט</th><th>רשימת התכנייה</th><th>תפקידים</th><th>שמע/וידאו</th></tr></thead><tbody>${values(D.scenes).map(s=>{let ts=txts(s.id),ps=psFor(s.id),rs=values(D.roles).filter(r=>r.s===s.id),av=D.media.filter(m=>m.target===s.id);let c=(n,t)=>`<button class="cell ${n?'':'absent'}" data-action="unit" data-value="${s.id}">${n?esc(t):'לא נמצאה רשומה'}</button>`;return `<tr><td>${btn(esc(s.title),'unit',s.id,'row-name')}<br><span class="source-locator">${esc(short(s.id))}</span></td><td>${c(ts.length,ts.map(t=>short(t.id)).join(' · '))}${s.id.endsWith('S10')?'<br>'+badge('כותרות, ללא גוף השיר','warn'):''}</td><td>${c(ps.length,ps.map(p=>short(p.id)).join(' · '))}</td><td>${c(rs.length,rs.length+' תפקידים')}${rs.some(r=>!D.persons[r.person])?'<br>'+badge('שיוך שחקנים חסר','warn'):''}</td><td>${c(av.length,av.length+' רשומות')}</td></tr>`}).join('')}</tbody></table></div><div class="banner">S4 ו־S8 הן הפסקות במיפתוח. T1 הוא שער ההצגה ומפנה ל־A, ולכן אינו מופיע כאן כאילו היה S נוסף. אין רשומות M מזוהות עם ההצגה; אין פירוש הדבר שלא הייתה מוזיקה.</div></div><div class="grid3">${[A+'-S10',A+'-S12',A+'-S3'].map(s=>`<div class="panel"><span class="kicker">כניסה לבעיה מחקרית</span><h3>${esc(label(s))}</h3><p class="small">${s.endsWith('S10')?'כותרות בטקסט; מילות השיר בתכנייה; שמע מקושר במיפתוח.':s.endsWith('S12')?'טקסט ושמונה תפקידים, ללא רשומת תכנייה וללא זיהויי שחקנים.':'שיר שנכתב בנפרד בתוך העד, עם סימון MOVE ליעד קריאה אחר.'}</p>${btn('פתיחת תיק היחידה','unit',s)}</div>`).join('')}</div>`}
function sourcesHTML(){let inv=sheet('תכולת תיקים').relevant_records;return `<div class="grid3"><article class="media-card"><button class="img-btn" data-action="program" data-value="1"><img src="${imgSrc(1)}" alt="שער תכניית כי תצא למלחמה"></button><div class="inner"><h3>התכנייה</h3><p>שני צילומים; שש יחידות P. אפשר לראות הן את סדר הערב והן את מילות השירים.</p>${btn('רשימה ומילות הטנדר','program','2')}</div></article><article class="media-card"><div class="inner"><span class="kicker">טקסט מקודד</span><h3>קובץ ה־XML</h3><p>ייצוא Word Flat OPC: 21 יחידות T, 64 סימוני עמוד ו־529 הערות. צבעים, מחיקות וסימוני עריכה נשמרים.</p>${btn('קריאת המקור','jump',A+'-T1')}${btn('הורדת XML המקור','sourceXML')}<div class="banner">אין כאן סריקות של 64 דפי המחזה. סמני העמוד הם עוגני ניווט בטקסט, לא תמונות שהוצגו כאילו צורפו.</div></div></article><article class="media-card"><div class="inner"><span class="kicker">מלאי ≠ קבצים זמינים</span><h3>כרזות ועיתונות</h3><p>במלאי רשומים חמישה פריטי כרזה ושלושה פריטי עיתונות. לא נמצאו רשומות של ההצגה בגיליונות המפורטים האלה.</p>${inv.map(r=>recordButton(r,String(r.values[4]).trim()+': '+r.values[6]+' פריטים')).join('')}</div></article></div><div class="panel" style="margin-top:22px"><h2>שמע ווידאו מקושרים</h2><p class="small">חמש רשומות בעלות שיוך עקבי. הקישורים נשמרו כפי שהם בגיליון; תקינות ההשמעה באתרים החיצוניים לא נבדקה. רשומה סותרת נוספת מופיעה בטאב הבדיקות.</p>${D.media.map(mediaHTML).join('')}</div><div class="panel"><h2>יחידות התכנייה</h2><div class="grid3">${values(D.graphics).map(g=>`<div class="step"><b>${esc(g.note||g.kind)}</b><span>${esc(short(g.id))} · עמוד ${g.logical_page} · צילום ${g.image_page}</span>${btn('פתחו','graphic',g.id)}</div>`).join('')}</div></div>`}
function notesAnalysis(){let cats=[...new Set(values(D.footnotes).flatMap(f=>f.categories))].sort((a,b)=>a.localeCompare(b,'he'));let c=STATE.category;let rows=sourceOrder().map(t=>({t,n:D.segments[t].categories[c]||0,total:D.segments[t].footnote_count}));let max=Math.max(1,...rows.map(r=>r.n));return `<div class="panel"><h2>מן הדפוס בהערות אל המקום בטקסט</h2><p>התרשים סופר הערות שבהן מופיע התיוג <b>„אזכור ${esc(c)}”</b>. לחיצה על שורה פותחת את ההערות ואת מקומן המדויק. זו קריאה של שכבת התיוג המחקרית — לא ספירה אוטומטית של כל האזכורים במחזה.</p><div class="chart-filter"><label>קטגוריה <select id="categorySelect">${cats.map(k=>`<option ${k===c?'selected':''}>${esc(k)}</option>`).join('')}</select></label><span class="small">${rows.reduce((n,r)=>n+r.n,0)} הערות בקטגוריה · הערה יכולה לשאת יותר מקטגוריה אחת</span></div>${rows.filter(r=>r.total||r.n).map(r=>`<div class="plot-row"><button data-action="categoryNotes" data-value="${r.t}|${esc(c)}">${esc(short(r.t))} · ${esc(D.text_records[r.t].title).slice(0,37)}</button><div class="bar-track"><div class="bar" style="width:${100*r.n/max}%"></div></div><span>${r.n}</span></div>`).join('')}<div class="banner">מספר ההערות מושפע מאורך המקטע ומעבודת המהדירים. אפס אינו הוכחה שאין נושא כזה בטקסט. מפת הכיסוי סופרת רשומות; התרשים כאן סופר הערות — אין לערבב את יחידות הספירה.</div></div><div class="panel"><h2>מורכבות העריכה לפי מקטע</h2><div class="table-scroll"><table class="coverage"><thead><tr><th>מקטע</th><th>הערות</th><th>מקטעי עיצוב: כתב יד</th><th>מחיקה דרמטורגית</th><th>הוראות בימוי</th></tr></thead><tbody>${sourceOrder().map(t=>{let z=D.segments[t];return `<tr><td>${btn(esc(short(t))+' · '+esc(D.text_records[t].title),'jump',t,'row-name')}</td><td>${z.footnote_count}</td><td>${z.semantics_runs.hand||0}</td><td>${z.semantics_runs.dram_del||0}</td><td>${z.semantics_runs.stage||0}</td></tr>`}).join('')}</tbody></table></div><p class="small">מקטעי עיצוב הם runs של Word, לא מספר פעולות עריכה: מילה אחת עשויה להתחלק לכמה runs. המספרים שימושיים לניווט ולא להסקה היסטורית על „כמה תיקונים נעשו”.</p></div>`}
function openCategoryNotes(value){let[t,c]=value.split('|');let fs=values(D.footnotes).filter(f=>f.categories.includes(c)&&f.occurrences.some(o=>PBY['xml-p'+String(o.p).padStart(4,'0')]?.t===t));pop('קריאה מרחוק → הערה → טקסט',`<h2>${esc(c)} · ${esc(short(t))}</h2><p>${fs.length} הערות מסומנות במקטע ${esc(D.text_records[t].title)}</p>${fs.map(f=>`<div class="finding"><p>${esc(f.text.slice(0,330))}</p>${btn('הערה '+f.display_number+' ומקורה','note',f.id)}</div>`).join('')||'<p>לא נמצאו הערות מסומנות בקטגוריה הזאת.</p>'}`)}
function castAtlasHTML(){
 let rows=values(D.scenes).map(scene=>({scene,roles:castOf(scene.id)})).filter(x=>x.roles.length);
 return `<section class="panel"><div class="section-head"><h2>מי גילם איזה תפקיד?</h2><span class="small">${values(D.roles).length} תפקידים · ${values(D.roles).filter(r=>!!D.persons[r.person]).length} שיוכים מזוהים · ${values(D.roles).filter(r=>!D.persons[r.person]).length} לא מזוהים</span></div><p>המידע מגיע מגיליון „תפקידים מקושרים בהצגה” ונקשר לישויות (per). אלה שיוכים מתועדים ולא תוצאה של ניחוש מן הדיאלוג. כל שם, תפקיד ויחידה ניתנים לפתיחה.</p>${rows.map(x=>`<div class="cast-atlas-section"><h3>${btn(esc(x.scene.title),'unit',x.scene.id,'row-name')}</h3><div class="cast-cards">${x.roles.map(r=>`<div class="cast-card"><button data-action="role" data-value="${esc(r.id)}"><b>${esc(r.character)}</b><small>${esc(short(r.id))}</small></button>${D.persons[r.person]?btn(esc(r.actor),'person',r.person,'actor-link'):'<span class="cast-unresolved">אין שיוך שחקן במיפתוח</span>'}</div>`).join('')}</div></div>`).join('')}<div class="banner">„בחזית המלך פיק” כוללת שמונה תפקידים ב־XML ובגיליון, אך שיוכי השחקנים חסרים. אין להשלים אותם מרשימת צוות ההצגה.</div></section>`;
}
function heatmapHTML(){
 const all=values(D.footnotes),categories=[...new Set(all.flatMap(f=>f.categories))].filter(Boolean).sort((a,b)=>a.localeCompare(b,'he'));
 const rows=sourceOrder().map(t=>({t,segment:D.segments[t]}));let max=Math.max(1,...rows.flatMap(r=>categories.map(c=>r.segment.categories[c]||0)));
 return `<div class="panel"><div class="section-head"><h2>מפת צפיפות התיוג בהערות ה־XML</h2><span class="small">שכבה קיימת · 529 הערות שוליים · לא שכבת Excel החדשה</span></div><p>מפת חום של <b>הערות שתויגו בקטגוריות מתוך תוכן הערות המהדירים</b>. יחידת הספירה היא הערת שוליים משויכת למקטע, ולא הופעת מילה אוטומטית. לחיצה על תא פותחת את ההערות ואת מיקומן. השכבה החדשה שנמסרה בטופס Excel עדיין ריקה.</p><div class="table-scroll"><table class="coverage tag-matrix"><thead><tr><th>מקטע טקסט</th>${categories.map(c=>`<th>${esc(c)}</th>`).join('')}<th>סה״כ הערות</th></tr></thead><tbody>${rows.map(({t,segment})=>`<tr><td>${btn(esc(short(t))+' · '+esc(D.text_records[t].title),'jump',t,'row-name')}</td>${categories.map(c=>{const n=segment.categories[c]||0;return `<td><button class="matrix-cell" style="--intensity:${n/max}" data-action="categoryNotes" data-value="${esc(t+'|'+c)}" title="${esc(c)} · ${esc(t)}: ${n} הערות" aria-label="${n} הערות בקטגוריה ${esc(c)} במקטע ${esc(t)}">${n||'·'}</button></td>`}).join('')}<td>${segment.footnote_count}</td></tr>`).join('')}</tbody></table></div><p class="small">הצגה במקביל לספירות לפי אורך תדרוש נרמול לפי מספר מילים או פסקאות. הנתונים אינם מודדים שכיחות תופעה בלי תלות ברמת פעילות התיוג.</p></div>`;
}
function taggingHTML(){
 const groups=[['תיוגי שפה','שפת הקטע, צורתו במקור, תרגום וסוג לשוני. אפשר להציג שכבות שפה על הטקסט ולחקור מעברי שפה לאורך המחזה.'],['הערות שוליים','הערות מסוגים שונים עם מיקום. יש לשמור אותן בנפרד מן ההערות שכבר מוטמעות ב־Word XML עד לזיהוי מאומת.'],['מונחים','מונחים, קטגוריות ורשתות. אלה ממדים שונים: mention, classification, membership; אין לאחד אותם לעמודה אחת.']];
 const count=TAG.records.length,ct=TAG.alignment_status_counts||{},ready=(TAG.records||[]).filter(r=>r.alignment?.status==='anchored_exact');
 return `<section class="panel"><div class="section-head"><h2>שכבת תיוג נוספת — תשתית סנכרון</h2><span class="small">קובץ ${esc(TAG.source?.name||'לא נטען')} · ${count} רשומות</span></div>${!count?'<div class="banner problem"><b>אין עדיין רשומות תיוג בקובץ.</b> שלושת הטאבים מכילים שורת כותרות בלבד. הממשק אינו מציג כאן מספרי שפות, מונחים או רשתות מומצאים. אפשר לעיין במבנה ולהחליף בהמשך את קובץ הקלט בקובץ מאוכלס.</div>':''}<div class="grid3">${groups.map(([name,desc])=>`<article class="step"><b>${name} · ${TAG.counts[name]||0} רשומות</b><span>${desc}</span><small class="source-locator">${esc((TAG.schema[name]||[]).join(' · '))}</small></article>`).join('')}</div><h3>סנכרון עם ה־XML</h3><p>לכל שורה נשמרים הטאב, שורת הגיליון והשדות המקוריים. „מזהה מיקום” נבדק מול עוגן פסקה / מזהה T; ציטוט נחשב למעוגן במילה רק כשנמצא מופע מדויק יחיד בהקשרו. התאמה עמומה נשארת בבירור ולא הופכת לקישור ודאי.</p><div class="layer-status-grid">${[['anchored_exact','מקטע מדויק ומזוהה'],['paragraph_only','פסקה מזוהה ללא טווח'],['segment_only','יחידת T ללא טווח'],['ambiguous','כמה התאמות אפשריות'],['unresolved','לא ניתן לעגן']].map(([code,title])=>`<div><b>${ct[code]||0}</b><span>${title}</span></div>`).join('')}</div>${ready.length?`<h3>תיוגים מעוגנים בטקסט</h3>${ready.map(r=>`<div class="finding">${btn(esc(r.fields['מונח']||r.fields['טקסט']||r.sheet),'tagrecord',r.id)} · ${btn('למיקום בטקסט','jump',r.alignment.t+'|'+r.alignment.paragraph)}</div>`).join('')}`:''}<div class="banner"><b>בקריאה רציפה:</b> הדגשה מדויקת בתוך המילה/המשפט, עם פתיחת רשומה ותצוגת מקור. <b>בקריאה מרחוק:</b> מפת צפיפות לפי T, השוואת שפות, קטגוריות, רשתות ומעברים לאורך הרצף — רק לאחר שיהיו רשומות מאומתות.</div></section>`;
}
function openTagRecord(id){const r=TAG.records.find(x=>x.id===id);if(!r)return;pop('תיוג מחקרי חדש · מקור הגיליון',`<h2>${esc(r.sheet)}</h2>${dl(r.fields)}<p class="small">${esc(r.source_cell)} · סנכרון: ${esc(r.alignment.status)} · ${esc(r.alignment.reason||'')}</p>${r.alignment?.paragraph?btn('לטקסט','jump',(r.alignment.t||'')+'|'+r.alignment.paragraph):''}`)}
function scenariosHTML(){let so=[];sourceOrder().forEach(t=>{let s=D.text_records[t].target;if(s!==A&&!so.includes(s))so.push(s)});return `<div class="panel"><h2>אותן יחידות — שתי קריאות</h2><p>ברירת המחדל של כל רצף נלקחת מן הסדר המתועד בו: סדר T במקור לעומת שדה הסדר ב־PS. אלה שני בסיסים שונים לארגון, לא שתי הוכחות לשני ערבים היסטוריים.</p><div class="grid2">${[[programOrder().map(p=>p.target),'לפי התכנייה'],[so,'לפי הטקסט']].map(([seq,title])=>`<div class="compare-col"><h3>${title}</h3><div class="sequence">${seq.map(s=>`<button data-action="unit" data-value="${s}" class="${s.endsWith('S12')?'solo':''}">${esc(label(s))}</button>`).join('')}</div></div>`).join('')}</div><div class="detail-links">${btn('צור קריאה ניסיונית מן התכנייה','newCustom')}</div></div>${STATE.custom?customHTML():''}`}
function customHTML(){let seq=STATE.custom.seq;return `<div class="panel"><div class="section-head"><h2>הקריאה הניסיונית שלי</h2>${btn('ייצוא בחירות','exportCustom')}</div><p class="small">שינויים מקומיים בדפדפן בלבד. כל יחידה נשארת מחוברת לעדויותיה; הרשומות והקריאות המקוריות אינן משתנות.</p>${seq.map((s,i)=>`<div class="custom-row"><div class="text">${btn(esc(label(s)),'unit',s)} ${!psFor(s).length?badge('ללא רשומת תכנייה','proposal'):''}</div>${btn('קודם','moveCustom',i+'|-1')}${btn('אחר כך','moveCustom',i+'|1')}${btn('הוצאה מהקריאה','removeCustom',String(i))}</div>`).join('')}<h3 style="margin-top:17px">יחידות שאינן בקריאה</h3><div class="pills">${keys(D.scenes).filter(s=>!seq.includes(s)).map(s=>btn('הוספת '+esc(label(s)),'addCustom',s)).join('')}</div><div class="banner">${seq.includes(A+'-S12')?'הוספת „בחזית המלך פיק” משלבת טקסט שאינו ברשימת התכנייה. סדרו כאן הוא בחירה שלך, לא מסקנה חדשה מן המקורות.':'הקריאה כוללת כרגע רק יחידות מן התכנייה, אך שינוי סדר הוא עדיין בחירה פרשנית שיש לנמק.'}</div><label class="small">נימוק הבחירה <textarea id="customReason" rows="3" style="width:100%;padding:10px;border:1px solid var(--line);border-radius:6px">${esc(STATE.custom.reason||'')}</textarea></label>${btn('שמירת הנימוק בדפדפן','saveReason')}</div>`}

